// Get the input data and context
const pingOutput = items[0].json;
const hostname = $node["Form Debug"].json.Hostname || pingOutput.Hostname || "Unknown Host";
const ipAddress = pingOutput['IP Address'] || $node["Form Debug"].json['IP Address'];

// Check if ping was successful by looking for patterns in stdout
const isOnline = pingOutput.stdout && 
  pingOutput.stdout.includes('0% packet loss');

// Extract useful statistics if available
let pingStats = {};
if (pingOutput.stdout && isOnline) {
  // Extract packet statistics
  const packetMatch = pingOutput.stdout.match(/(\d+) packets transmitted, (\d+) received, (\d+)% packet loss/);
  if (packetMatch) {
    pingStats.transmitted = parseInt(packetMatch[1]);
    pingStats.received = parseInt(packetMatch[2]);
    pingStats.packetLoss = parseInt(packetMatch[3]);
  }

  // Extract round-trip time statistics
  const rttMatch = pingOutput.stdout.match(/rtt min\/avg\/max\/mdev = ([\d\.]+)\/([\d\.]+)\/([\d\.]+)\/([\d\.]+)/);
  if (rttMatch) {
    pingStats.rttMin = parseFloat(rttMatch[1]);
    pingStats.rttAvg = parseFloat(rttMatch[2]);
    pingStats.rttMax = parseFloat(rttMatch[3]);
  }
} else {
  // Set default stats for offline servers
  pingStats = {
    transmitted: 4,
    received: 0,
    packetLoss: 100,
    rttMin: 0,
    rttAvg: 0,
    rttMax: 0
  };
}

// Return the modified data
return [
  {
    json: {
      Hostname: hostname,
      'IP Address': ipAddress,
      isOnline: isOnline,
      stats: pingStats,
      timestamp: new Date().toISOString(),
      errorMessage: pingOutput.stderr || ""
    }
  }
];

